 * Opens a JSON-file-backed book store. The whole list is kept in memory and
 * rewritten atomically (temp file + rename) on every change, one write at a time.
 */
export async function openStore(file) {
  let books = await load(file);
  let queue = Promise.resolve();

  // Apply a change to a copy, persist it, and only then make it visible.
  function update(change) {
    const run = queue.then(async () => {
      const next = structuredClone(books);
      const result = change(next);
      await persist(file, next);
      books = next;
      return result;
    });
    queue = run.catch(() => {});
    return run;
  }

  return {
    list: () => structuredClone(books),
    get: (id) => {
      const book = books.find((b) => b.id === id);
      return book ? structuredClone(book) : null;
    },
    add: (input) => {
      const { values, errors } = validateBook(input);
      if (Object.keys(errors).length) {
        const err = new Error('Invalid book');
        err.errors = errors;
        throw err;
      }
      return update((list) => {
        const book = {
          id: newId(list),
          ...values,
          status: 'reading',
          addedAt: new Date().toISOString(),
          finishedAt: null,
        };
        list.push(book);
        return structuredClone(book);
      });
    },
    finish: (id) =>
      update((list) => {
        const book = list.find((b) => b.id === id);
        if (!book) return null;
        if (book.status !== 'finished') {
          book.status = 'finished';
          book.finishedAt = new Date().toISOString();
        }
        return structuredClone(book);
      }),
  };
