{"path": "/workspace/src/views.js", "content": "import { LIMITS } from './store.js';

export function escape(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function formatDate(iso) {
  if (!iso) return '';
  return new Date(iso).toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
}

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escape(title)}</title>
<style>
  body { font: 16px/1.5 system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; color: #222; }
  a { color: #1a5fb4; }
  h1 a { color: inherit; text-decoration: none; }
  ul.books { list-style: none; padding: 0; }
  ul.books li { display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding: .5rem 0; border-bottom: 1px solid #eee; }
  .muted { color: #666; font-size: .9rem; }
  form.inline { margin: 0; }
  label { display: block; margin-top: .75rem; font-weight: 600; }
  input[type=text], textarea { width: 100%; box-sizing: border-box; padding: .4rem; font: inherit; }
  textarea { min-height: 6rem; }
  button { margin-top: .75rem; padding: .3rem .8rem; font: inherit; cursor: pointer; }
  form.inline button { margin-top: 0; }
  .error { color: #b00020; font-size: .9rem; }
  .notes { white-space: pre-wrap; background: #f7f7f7; padding: .75rem; border-radius: 4px; }
</style>
</head>
<body>
<h1><a href="/">My books</a></h1>
${body}
</body>
</html>`;
}

function finishButton(book, from) {
  return `<form class="inline" method="post" action="/books/${escape(book.id)}/finish">
  <input type="hidden" name="from" value="${from}">
  <button type="submit">Mark finished</button>
</form>`;
}

function bookList(books, emptyText, renderExtra) {
  if (!books.length) return `<p class="muted">${emptyText}</p>`;
  const items = books
    .map(
      (b) => `<li>
  <span><a href="/books/${escape(b.id)}">${escape(b.title)}</a> <span class="muted">by ${escape(b.author)}</span></span>
  ${renderExtra(b)}
</li>`,
    )
    .join('\n');
  return `<ul class="books">\n${items}\n</ul>`;
}

export function homePage(books, { values = {}, errors = {} } = {}) {
  const reading = books
    .filter((b) => b.status === 'reading')
    .sort((a, b) => b.addedAt.localeCompare(a.addedAt));
  const finished = books
    .filter((b) => b.status === 'finished')
    .sort((a, b) => b.finishedAt.localeCompare(a.finishedAt));

  const field = (name) =>
    errors[name] ? `<div class="error" id="${name}-error">${escape(errors[name])}</div>` : '';

  return layout(
    'My books',
    `<h2>Currently reading</h2>
${bookList(reading, 'Nothing on the go right now.', (b) => finishButton(b, 'home'))}

<h2>Finished</h2>
${bookList(finished, 'No finished books yet.', (b) => `<span class="muted">${formatDate(b.finishedAt)}</span>`)}

<h2>Add a book</h2>
<form method="post" action="/books">
  <label for="title">Title</label>
  <input type="text" id="title" name="title" required maxlength="${LIMITS.title}" value="${escape(values.title)}">
  ${field('title')}
  <label for="author">Author</label>
  <input type="text" id="author" name="author" required maxlength="${LIMITS.author}" value="${escape(values.author)}">
  ${field('author')}
  <label for="notes">Notes</label>
  <textarea id="notes" name="notes" maxlength="${LIMITS.notes}">${escape(values.notes)}</textarea>
  ${field('notes')}
  <button type="submit">Add book</button>
</form>`,
  );
}

export function bookPage(book, shareUrl) {
  const status =
    book.status === 'finished'
      ? `Finished ${formatDate(book.finishedAt)}`
      : `Reading since ${formatDate(book.addedAt)}`;
  const notes = book.notes
    ? `<div class="notes">${escape(book.notes)}</div>`
    : '<p class="muted">No notes.</p>';

  return layout(
    `${book.title} by ${book.author}`,
    `<h2>${escape(book.title)}</h2>
<p>by ${escape(book.author)}</p>
<p class="muted">${status}</p>
${book.status === 'reading' ? finishButton(book, 'book') : ''}
<h3>Notes</h3>
${notes}
<h3>Share</h3>
<label for="share" class="muted">Link to this book</label>
<input type="text" id="share" readonly value="${escape(shareUrl)}" onclick="this.select()">
<p><a href="/">&larr; All books</a></p>`,
  );
}

export function notFoundPage() {
  return layout('Not found', `<p>That book isn't here.</p><p><a href="/">&larr; All books</a></p>`);
}

export function errorPage(message) {
  return layout('Error', `<p>${escape(message)}</p><p><a href="/">&larr; All books</a></p>`);
}
"}

