const MAX_BODY_BYTES = 64 * 1024;

class HttpError extends Error {
  constructor(status, message) {
    super(message);
    this.status = status;
  }
}

/** Returns a Node `http` request handler backed by the given store. */
export function createApp(store) {
  return async function handler(req, res) {
    try {
      await route(store, req, res);
    } catch (err) {
      const status = err instanceof HttpError ? err.status : 500;
      if (status === 500) console.error(err);
      sendHtml(res, status, errorPage(status === 500 ? 'Something went wrong.' : err.message));
    }
  };
}

async function route(store, req, res) {
  const { pathname } = new URL(req.url, 'http://localhost');
  const method = req.method;

  if (pathname === '/') {
    if (method !== 'GET' && method !== 'HEAD') return methodNotAllowed(res, 'GET');
    return sendHtml(res, 200, homePage(store.list()));
  }

  if (pathname === '/books') {
    if (method !== 'POST') return methodNotAllowed(res, 'POST');
    const form = await readForm(req);
    try {
      const book = await store.add(form);
      return redirect(res, `/books/${book.id}`);
    } catch (err) {
      if (!err.errors) throw err;
      return sendHtml(res, 400, homePage(store.list(), { values: form, errors: err.errors }));
    }
  }

  let match = pathname.match(/^\/books\/([A-Za-z0-9_-]+)\/finish$/);
  if (match) {
    if (method !== 'POST') return methodNotAllowed(res, 'POST');
    const form = await readForm(req);
    const book = await store.finish(match[1]);
    if (!book) return sendHtml(res, 404, notFoundPage());
    return redirect(res, form.from === 'book' ? `/books/${book.id}` : '/');
  }

  match = pathname.match(/^\/books\/([A-Za-z0-9_-]+)$/);
  if (match) {
    if (method !== 'GET' && method !== 'HEAD') return methodNotAllowed(res, 'GET');
    const book = store.get(match[1]);
    if (!book) return sendHtml(res, 404, notFoundPage());
    return sendHtml(res, 200, bookPage(book, shareUrl(req, book)));
  }

  return sendHtml(res, 404, notFoundPage());
}

function shareUrl(req, book) {
  const proto = String(req.headers['x-forwarded-proto'] ?? 'http').split(',')[0].trim();
  const host = req.headers['x-forwarded-host'] ?? req.headers.host ?? 'localhost';
  return `${proto}://${host}/books/${book.id}`;
}

async function readForm(req) {
  const chunks = [];
  let size = 0;
  for await (const chunk of req) {
    size += chunk.length;
    if (size > MAX_BODY_BYTES) throw new HttpError(413, 'That form was too large.');
    chunks.push(chunk);
  }
  return Object.fromEntries(new URLSearchParams(Buffer.concat(chunks).toString('utf8')));
}

function sendHtml(res, status, html) {
  res.writeHead(status, {
    'Content-Type': 'text/html; charset=utf-8',
    'Content-Length': Buffer.byteLength(html),
    'X-Content-Type-Options': 'nosniff',
  });
  res.end(res.req?.method === 'HEAD' ? undefined : html);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

function methodNotAllowed(res, allow) {
  res.setHeader('Allow', allow);
  sendHtml(res, 405, errorPage('Method not allowed.'));
}
"}

