import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import { createApp } from '../src/app.js';
import { openStore } from '../src/store.js';

let dir;
let dataFile;
let servers = [];

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), 'books-'));
  dataFile = join(dir, 'books.json');
});

afterEach(async () => {
  await Promise.all(servers.map((s) => new Promise((r) => s.close(r))));
  servers = [];
  await rm(dir, { recursive: true, force: true });
});

async function start() {
  const store = await openStore(dataFile);
  const server = createServer(createApp(store));
  await new Promise((r) => server.listen(0, '127.0.0.1', r));
  servers.push(server);
  const base = `http://127.0.0.1:${server.address().port}`;
  return {
    get: (path) => fetch(base + path),
    post: (path, fields) =>
      fetch(base + path, {
        method: 'POST',
        body: new URLSearchParams(fields),
        redirect: 'manual',
      }),
  };
}

function section(html, heading) {
  const start = html.indexOf(`<h2>${heading}</h2>`);
  const end = html.indexOf('<h2>', start + 1);
  return html.slice(start, end === -1 ? undefined : end);
}

describe('books app', () => {
  it('adds a book, shows it as reading, then finished', async () => {
    const app = await start();

    const home = await (await app.get('/')).text();
    expect(home).toContain('Nothing on the go right now.');
    expect(home).toContain('No finished books yet.');

    const added = await app.post('/books', { title: 'Dune', author: 'Frank Herbert', notes: 'Spice.' });
    expect(added.status).toBe(303);
    const bookPath = added.headers.get('location');
    expect(bookPath).toMatch(/^\/books\/[A-Za-z0-9_-]+$/);

    let html = await (await app.get('/')).text();
    expect(section(html, 'Currently reading')).toContain('Dune');
    expect(section(html, 'Finished')).not.toContain('Dune');

    const finished = await app.post(`${bookPath}/finish`, { from: 'home' });
    expect(finished.status).toBe(303);
    expect(finished.headers.get('location')).toBe('/');

    html = await (await app.get('/')).text();
    expect(section(html, 'Currently reading')).not.toContain('Dune');
    expect(section(html, 'Finished')).toContain('Dune');
  });

  it('shows title, author, notes and a shareable link on the book page', async () => {
    const app = await start();
    const added = await app.post('/books', { title: 'Emma', author: 'Jane Austen', notes: 'Line one\nLine two' });
    const bookPath = added.headers.get('location');

    const res = await app.get(bookPath);
    expect(res.status).toBe(200);
    const html = await res.text();
    expect(html).toContain('<h2>Emma</h2>');
    expect(html).toContain('by Jane Austen');
    expect(html).toContain('Line one\nLine two');
    expect(html).toMatch(new RegExp(`value="http://127\\.0\\.0\\.1:\\d+${bookPath}"`));
    expect(html).toContain('Mark finished');

    const fin = await app.post(`${bookPath}/finish`, { from: 'book' });
    expect(fin.headers.get('location')).toBe(bookPath);
    const after = await (await app.get(bookPath)).text();
    expect(after).toContain('Finished ');
    expect(after).not.toContain('Mark finished');
  });

  it('keeps books after a restart', async () => {
    const first = await start();
    const added = await first.post('/books', { title: 'Middlemarch', author: 'George Eliot' });
    const bookPath = added.headers.get('location');
    await first.post(`${bookPath}/finish`, {});

    const saved = JSON.parse(await readFile(dataFile, 'utf8'));
    expect(saved.books).toHaveLength(1);
    expect(saved.books[0]).toMatchObject({ title: 'Middlemarch', status: 'finished' });

    const second = await start();
    const html = await (await second.get(bookPath)).text();
    expect(html).toContain('Middlemarch');
    expect(html).toContain('Finished ');
  });

  it('rejects a book without a title and keeps what was typed', async () => {
    const app = await start();
    const res = await app.post('/books', { title: '  ', author: 'Someone', notes: 'kept' });
    expect(res.status).toBe(400);
    const html = await res.text();
    expect(html).toContain('Title is required.');
    expect(html).toContain('value="Someone"');
    expect(html).toContain('>kept</textarea>');
    expect(JSON.parse(await readFile(dataFile, 'utf8').catch(() => '{"books":[]}')).books).toHaveLength(0);
  });

  it('escapes user input', async () => {
    const app = await start();
    const added = await app.post('/books', { title: '<script>x</script>', author: 'A & "B"', notes: '<b>hi</b>' });
    const html = await (await app.get(added.headers.get('location'))).text();
    expect(html).not.toContain('<script>x</script>');
    expect(html).toContain('&lt;script&gt;x&lt;/script&gt;');
    expect(html).toContain('A &amp; &quot;B&quot;');
    expect(html).toContain('&lt;b&gt;hi&lt;/b&gt;');
  });

  it('returns 404 for unknown books', async () => {
    const app = await start();
    expect((await app.get('/books/nope')).status).toBe(404);
    expect((await app.post('/books/nope/finish', {})).status).toBe(404);
    expect((await app.get('/elsewhere')).status).toBe(404);
  });

  it('refuses to start on a corrupt data file instead of overwriting it', async () => {
    await writeFile(dataFile, '{not json');
    await expect(openStore(dataFile)).rejects.toThrow(/not valid JSON/);
    expect(await readFile(dataFile, 'utf8')).toBe('{not json');
  });
});
